import{_ as t,o as a,c as i,ag as r}from"./chunks/framework.D7xI0JV8.js";const f=JSON.parse('{"title":"Privacy Rails","description":"","frontmatter":{},"headers":[],"relativePath":"privacy-rails.md","filePath":"privacy-rails.md"}'),o={name:"privacy-rails.md"};function d(l,e,n,c,s,h){return a(),i("div",null,[...e[0]||(e[0]=[r(`<h1 id="privacy-rails" tabindex="-1">Privacy Rails <a class="header-anchor" href="#privacy-rails" aria-label="Permalink to &quot;Privacy Rails&quot;">​</a></h1><p>Privacy in zkde.fi is not a feature toggle — it is a proving pipeline. The system uses a commitment → nullifier → claim hash → relayer → settlement flow that enables private execution while retaining on-chain verifiability.</p><p>This page documents how private capital movement works, from deposit through withdrawal, across three enforcement tiers.</p><h2 id="the-pipeline" tabindex="-1">The Pipeline <a class="header-anchor" href="#the-pipeline" aria-label="Permalink to &quot;The Pipeline&quot;">​</a></h2><pre class="mermaid" data-mermaid-source="flowchart%20LR%0A%20%20DEP%5BDeposit%5D%20--%3E%20CMT%5BCommitment%3A%20hash%20of%20secret%20%2B%20nullifier%5D%0A%20%20CMT%20--%3E%20TREE%5BMerkle%20tree%20insertion%5D%0A%20%20TREE%20--%3E%20POOL%5BShielded%20pool%20state%5D%0A%20%20POOL%20--%3E%20WD%5BWithdraw%20intent%5D%0A%20%20WD%20--%3E%20NUL%5BNullifier%20reveal%3A%20prevents%20double-spend%5D%0A%20%20NUL%20--%3E%20CLAIM%5BClaim%20hash%3A%20binding%20proof%20of%20entitlement%5D%0A%20%20CLAIM%20--%3E%20RELAY%5BRelayer%20submission%3A%20optional%2C%20breaks%20tx-graph%20link%5D%0A%20%20RELAY%20--%3E%20SETTLE%5BSettlement%3A%20on-chain%20or%20L3%5D%0A%20%20SETTLE%20--%3E%20RCPT%5BReceipt%3A%20immutable%2C%20verifiable%5D">flowchart LR
  DEP[Deposit] --&gt; CMT[Commitment: hash of secret + nullifier]
  CMT --&gt; TREE[Merkle tree insertion]
  TREE --&gt; POOL[Shielded pool state]
  POOL --&gt; WD[Withdraw intent]
  WD --&gt; NUL[Nullifier reveal: prevents double-spend]
  NUL --&gt; CLAIM[Claim hash: binding proof of entitlement]
  CLAIM --&gt; RELAY[Relayer submission: optional, breaks tx-graph link]
  RELAY --&gt; SETTLE[Settlement: on-chain or L3]
  SETTLE --&gt; RCPT[Receipt: immutable, verifiable]</pre><h3 id="step-by-step" tabindex="-1">Step by Step <a class="header-anchor" href="#step-by-step" aria-label="Permalink to &quot;Step by Step&quot;">​</a></h3><ol><li><strong>Commitment generation</strong> — the user creates a commitment: <code>hash(secret, nullifier, amount)</code>. The secret stays private. The commitment is added to the pool&#39;s Merkle tree.</li><li><strong>Merkle tree state</strong> — the pool maintains a Merkle tree of all commitments. The current root is publicly readable; individual leaves are not.</li><li><strong>Withdrawal proof</strong> — to withdraw, the user generates a ZK proof that they know a leaf in the Merkle tree (their commitment) without revealing which one. They also reveal the nullifier to prevent double-spend.</li><li><strong>Claim hash</strong> — a binding hash that ties the withdrawal proof to a specific recipient and amount, without revealing the depositor.</li><li><strong>Relayer submission</strong> — optionally, a relayer submits the transaction on the user&#39;s behalf, so the withdrawal tx is not linked to the depositor&#39;s address.</li><li><strong>Settlement</strong> — the withdrawal is settled on-chain (Starknet L2) or via the Madara L3 path.</li><li><strong>Receipt</strong> — an immutable receipt is stored in the ReceiptRegistry.</li></ol><h2 id="privacy-tiers" tabindex="-1">Privacy Tiers <a class="header-anchor" href="#privacy-tiers" aria-label="Permalink to &quot;Privacy Tiers&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Tier</th><th>Proof Requirement</th><th>Relayer</th><th>Timing</th><th>Use Case</th></tr></thead><tbody><tr><td><strong>Strict</strong></td><td>Full ZK proof, Merkle inclusion proof, nullifier</td><td>No relayer — user submits directly</td><td>No delay</td><td>Maximum control, user manages own tx submission</td></tr><tr><td><strong>Standard</strong></td><td>Full ZK proof, Merkle inclusion proof, nullifier</td><td>Relayer submits on user&#39;s behalf</td><td>Configurable delay (batching)</td><td>Default tier — breaks depositor-withdrawer tx link</td></tr><tr><td><strong>Express</strong></td><td>Optimistic batch verification</td><td>Relayer with batch aggregation</td><td>Batched settlement</td><td>Lower-value flows where batching saves gas</td></tr></tbody></table><h2 id="privacy-circuits" tabindex="-1">Privacy Circuits <a class="header-anchor" href="#privacy-circuits" aria-label="Permalink to &quot;Privacy Circuits&quot;">​</a></h2><p>The privacy pipeline uses dedicated Circom circuits:</p><table tabindex="0"><thead><tr><th>Circuit</th><th>Purpose</th></tr></thead><tbody><tr><td><code>FullPrivacyWithdraw</code></td><td>Standard full-privacy withdrawal proof</td></tr><tr><td><code>FullPrivacyWithdrawHashed</code></td><td>Withdrawal with hashed recipient binding</td></tr><tr><td><code>FullPrivacyWithdrawWithChange</code></td><td>Withdrawal with change output (partial withdrawal)</td></tr><tr><td><code>PrivateDeposit</code></td><td>Commitment generation and Merkle insertion proof</td></tr><tr><td><code>PrivateWithdraw</code></td><td>Simplified privacy withdrawal</td></tr><tr><td><code>PoolMembership</code></td><td>Proves membership in a shielded pool without revealing position</td></tr></tbody></table><h2 id="selective-disclosure" tabindex="-1">Selective Disclosure <a class="header-anchor" href="#selective-disclosure" aria-label="Permalink to &quot;Selective Disclosure&quot;">​</a></h2><p>Selective disclosure means the user can prove specific properties about their private state without revealing the state itself:</p><ul><li>&quot;I have at least X collateral&quot; — without revealing the exact amount</li><li>&quot;My position has been open for at least Y days&quot; — without revealing the entry date</li><li>&quot;I passed the risk screening&quot; — without revealing the risk score</li></ul><p>This is implemented via the <code>SelectiveDisclosure</code> contract on Starknet Sepolia (<a href="https://sepolia.voyager.online/contract/0x00ab6791e84e2d88bf2200c9e1c2fb1caed2eecf5f9ae2989acf1ed3d00a0c77" target="_blank" rel="noreferrer"><code>0x00ab6791e84e2d88bf2200c9e1c2fb1caed2eecf5f9ae2989acf1ed3d00a0c77</code></a>) and the <code>BalanceAboveThreshold</code> and <code>TenureAboveThreshold</code> circuits.</p><h2 id="privacy-contracts" tabindex="-1">Privacy Contracts <a class="header-anchor" href="#privacy-contracts" aria-label="Permalink to &quot;Privacy Contracts&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Contract</th><th>Address</th><th>Purpose</th></tr></thead><tbody><tr><td>FullPrivacyPoolV2</td><td><a href="https://sepolia.voyager.online/contract/0x03dde5617d362a6f9202cd3955b4508e2bd6b1c5d35250153beeb6237c811559" target="_blank" rel="noreferrer"><code>0x03dde5617d362a6f9202cd3955b4508e2bd6b1c5d35250153beeb6237c811559</code></a></td><td>Main shielded pool with Merkle tree</td></tr><tr><td>SelectiveDisclosure</td><td><a href="https://sepolia.voyager.online/contract/0x00ab6791e84e2d88bf2200c9e1c2fb1caed2eecf5f9ae2989acf1ed3d00a0c77" target="_blank" rel="noreferrer"><code>0x00ab6791e84e2d88bf2200c9e1c2fb1caed2eecf5f9ae2989acf1ed3d00a0c77</code></a></td><td>Selective disclosure verifier</td></tr><tr><td>ConfidentialTransfer</td><td><a href="https://sepolia.voyager.online/contract/0x07fdc7c21ab074e7e1afe57edfcb818be183ab49f4bf31f9bf86dd052afefaa4" target="_blank" rel="noreferrer"><code>0x07fdc7c21ab074e7e1afe57edfcb818be183ab49f4bf31f9bf86dd052afefaa4</code></a></td><td>Private transfer with proof</td></tr><tr><td>FullyShieldedPool</td><td><a href="https://sepolia.voyager.online/contract/0x07fed6973cfc23b031c0476885ec87a401f1006bdc8ba58df2bd8611b38b5ff5" target="_blank" rel="noreferrer"><code>0x07fed6973cfc23b031c0476885ec87a401f1006bdc8ba58df2bd8611b38b5ff5</code></a></td><td>Fully shielded variant</td></tr></tbody></table><h2 id="privacy-api-endpoints" tabindex="-1">Privacy API Endpoints <a class="header-anchor" href="#privacy-api-endpoints" aria-label="Permalink to &quot;Privacy API Endpoints&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Method</th><th>Endpoint</th><th>Purpose</th></tr></thead><tbody><tr><td><code>POST</code></td><td><code>/api/v1/zkdefi/full_privacy/deposit/generate_commitment</code></td><td>Generate commitment for private deposit</td></tr><tr><td><code>POST</code></td><td><code>/api/v1/zkdefi/full_privacy/withdraw/generate_proof</code></td><td>Generate Merkle withdrawal proof</td></tr><tr><td><code>GET</code></td><td><code>/api/v1/zkdefi/full_privacy/merkle/root</code></td><td>Current Merkle root state</td></tr><tr><td><code>POST</code></td><td><code>/api/v1/zkdefi/privacy/deposit</code></td><td>Unified privacy deposit flow</td></tr><tr><td><code>POST</code></td><td><code>/api/v1/zkdefi/privacy/withdraw</code></td><td>Unified privacy withdraw flow</td></tr><tr><td><code>GET</code></td><td><code>/api/v1/zkdefi/compliance/profiles/{user_address}</code></td><td>Compliance and disclosure profile</td></tr></tbody></table><h2 id="extensions-beyond-capital-flows" tabindex="-1">Extensions Beyond Capital Flows <a class="header-anchor" href="#extensions-beyond-capital-flows" aria-label="Permalink to &quot;Extensions Beyond Capital Flows&quot;">​</a></h2><p>The same commitment → nullifier → claim hash rails are extended to:</p><ul><li><strong>Private voting</strong> — the <code>private_vote</code> circuit allows governance participation without revealing voting power or vote direction. Implemented via <code>DAOConstraintManager</code> (<a href="https://sepolia.voyager.online/contract/0x0101bd9710017c0870077dcf03bf6fe68a955d9f9b9922ed5d673afed7497fc2" target="_blank" rel="noreferrer"><code>0x0101bd9710017c0870077dcf03bf6fe68a955d9f9b9922ed5d673afed7497fc2</code></a>).</li><li><strong>Private lending</strong> — credit eligibility proofs via the <code>CreditEligibility</code> circuit. Proves collateral sufficiency without revealing portfolio composition.</li><li><strong>Compliance artifacts</strong> — disclosure proofs that satisfy compliance requirements without revealing raw private state.</li></ul><hr><p>Next: <a href="/docs/zkml-circuits.html">zkML + Circuit Stack</a> | <a href="/docs/proof-pipeline.html">Proof Pipeline</a> | <a href="/docs/contracts.html">Deployed Contracts</a></p>`,25)])])}const b=t(o,[["render",d]]);export{f as __pageData,b as default};
